pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNum, uint8 offset, uint256 deposit) public {
        // offset in [1, 20] to give the fuzzer room; blockNum can be anything
        uint256 target = blockNum + offset;
        vm.assume(target > blockNum); // ensure block.timestamp > pastBlockTime for first call
        vm.assume(deposit == 10 ether);

        // warp to a future timestamp so the require(block.timestamp > pastBlockTime) passes
        vm.warp(1000);
        vm.roll(blockNum);

        // make a first call to set pastBlockTime and potentially drain the contract
        address caller1 = makeAddr("caller1");
        vm.deal(caller1, deposit);
        vm.prank(caller1);
        c.fallback{value: deposit}();

        // advance to the chosen block where we will test the branching condition
        vm.warp(2000);
        vm.roll(target);

        address caller2 = makeAddr("caller2");
        vm.deal(caller2, deposit);
        vm.prank(caller2);
        c.fallback{value: deposit}();

        // After the second call:
        // - Reference sends balance if target % 15 == 0, so balance becomes 0.
        // - Buggy sends balance if target % 15 != 0, so balance becomes 0 in that opposite case.
        // The property: (balance == 0) iff (target % 15 == 0) for the reference.
        // The bug violates this when target % 15 != 0 but balance becomes 0.
        bool zeroBalance = address(c).balance == 0;
        bool condition = (target % 15 == 0);
        assertTrue(zeroBalance == condition);
    }
}

