pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initValue, uint256 initBlock, uint256 callValue, uint256 callBlock) public {
        // Restrict to admissible domain: initial call sets pastBlockTime, second call must have greater timestamp
        vm.assume(initBlock < callBlock);
        vm.assume(initValue == 10 ether);
        vm.assume(callValue == 10 ether);

        // Ensure block.number is not zero to avoid division modulo zero
        vm.assume(initBlock > 0 && callBlock > 0);

        // Ensure condition for the differentiating scenario: initBlock sets pastBlockTime but doesn't trigger transfer,
        // callBlock has block.number % 15 != 0 so reference doesn't transfer but buggy does
        vm.assume(initBlock % 15 != 0);
        vm.assume(callBlock % 15 != 0);

        // Sender address
        address sender = address(0x1234);
        vm.deal(sender, 30 ether);

        // First call: sets pastBlockTime, fund the contract, no transfer because block.number % 15 != 0
        vm.roll(initBlock);
        vm.warp(initBlock);
        vm.prank(sender);
        c.f{value: 10 ether}();

        // Second call: block.timestamp > pastBlockTime, block.number % 15 != 0
        vm.roll(callBlock);
        vm.warp(callBlock);
        vm.prank(sender);
        c.f{value: 10 ether}();

        // After second call with block.number % 15 != 0, reference keeps its balance (> 0), buggy transfers all
        assertTrue(address(c).balance > 0);
    }
}

