        amount = bound(amount, 0, 100 ether);
        vm.assume(amount != 10 ether); // we want to test calls that the reference rejects but the mutant might accept
        rollNumber = bound(rollNumber, 1, type(uint256).max);
        vm.roll(rollNumber);
        vm.warp(block.timestamp + 1);

        // Ensure contract has some balance to detect improper transfers
        vm.deal(address(c), 10 ether);

        address actor = address(0x1234);
        vm.deal(actor, amount);
        vm.prank(actor);

        bool ok;
        try c.fallback{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: Reference C reverts any fallback call not sending exactly 10 ether.
        // The mutant allows such calls (e.g., 0 ether) to succeed, updating pastBlockTime and potentially transferring balance.
        // Thus for any call with amount != 10 ether, the reference must revert.
        // The mutant breaks this by succeeding for some amount (e.g., 0 ether).
        assertTrue(!ok, "Reference should reject calls with incorrect value, but mutant might accept");
    }
}

